/// `0x089A` — 24 bytes.
const FEAT11: [u8; 24] = [
    0x9a, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x18, 0x00, 0x00, 0x00,
];

/// `0x089B` — 16 bytes.
const THEME12: [u8; 16] = [
    0x9b, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x01, 0x00, 0x00, 0x00,
];

/// `0x08A3` — 16 bytes.
const FEAT12: [u8; 16] = [
    0xa3, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00,
];

/// Appends the end of the globals substream: always write it *last*.
pub fn write_eof(out: &mut Vec<u8>) {
    push_record(out, 0x000A, &EOF);
}

/// Appends the fixed part of the globals substream (everything but `EOF`).
pub fn write_globals(out: &mut Vec<u8>) {
    push_record(out, 0x0809, &BOF);
    push_record(out, 0x00E1, &INTERFACE_HDR);
    push_record(out, 0x00C1, &MMS);
    push_record(out, 0x00E2, &INTERFACE_END);
    push_record(out, 0x005C, &WRITE_ACCESS);
    push_record(out, 0x0042, &CODEPAGE);
    push_record(out, 0x0161, &DSF);
    push_record(out, 0x01C0, &EXCEL9_FILE);
    push_record(out, 0x013D, &TAB_ID);
    push_record(out, 0x009C, &BUILTIN_FMT_CNT);
    push_record(out, 0x0019, &WINDOW_PROTECT);
    push_record(out, 0x0012, &PROTECT);
    push_record(out, 0x0013, &PASSWORD);
    push_record(out, 0x01AF, &PROTECT_REV4);
    push_record(out, 0x01BC, &PROTECTION_REV4);
    for (ifnt, ifmt) in XF_PAIRS {
        let xf = xf(ifnt, ifmt);
        push_record(out, 0x00E0, &xf);
    }
    for i in 0..XF_PAIRS.len() as u16 { xfext(i, out); }
    for (i, name) in style_names().iter().enumerate() {
        style(16 + i as u16, name, out);
    }
    push_record(out, 0x003D, &WINDOW1);
    push_record(out, 0x0040, &BACKUP);
    push_record(out, 0x008D, &HIDE_OBJ);
    push_record(out, 0x0022, &DATE_MODE);
    push_record(out, 0x000E, &PRECISION);
    push_record(out, 0x01B7, &REFRESH_ALL);
    push_record(out, 0x00DA, &BOOK_BOOL);
    push_record(out, 0x087C, &FEAT_HDR);
    push_record(out, 0x088E, &FEAT);
    push_record(out, 0x0160, &USE_SELFS);
    push_record(out, 0x089A, &FEAT11);
    push_record(out, 0x08A3, &FEAT12);
    push_record(out, 0x008C, &COUNTRY);
    push_record(out, 0x01C1, &EXCEL9_NAMES);
    push_record(out, 0x0863, &BOOK_EXT);
    push_record(out, 0x0896, &ROUNDTRIP);
    push_record(out, 0x089B, &THEME12);
    push_record(out, 0x088C, &THEME);
}

#[cfg(test)]
mod tests {
    /// The 14698 byte reference stream Excel wrote (kept until the last
    /// literal part below is understood; see `docs/xls.md` §15.2).
    const REFERENCE: &[u8] = include_bytes!("../templates/globals.bin");

    fn ours() -> Vec<u8> {
        let mut v = Vec::new();
        super::write_globals(&mut v);
        v
    }

    /// Records whose payload depends on the workbook, so they are written by
    /// `write.rs` and cannot be compared here.
    fn is_content(kind: u16) -> bool {
        matches!(kind, 0x0031 | 0x041E)
    }

    #[test]
    #[ignore = "TODO(docs/xls.md §15.3): STYLE/StyleExt 的本地化名字与 28 种 XF 尾巴还没搬进表"]
    fn globals_match_the_reference() {
        let mut expected = Vec::new();
        let mut at = 0usize;
        while at + 4 <= REFERENCE.len() {
            let kind = u16::from_le_bytes([REFERENCE[at], REFERENCE[at + 1]]);
            let len = u16::from_le_bytes([REFERENCE[at + 2], REFERENCE[at + 3]]) as usize;
            if kind == 0x000A {
                break;
            }
            if !is_content(kind) {
                expected.extend_from_slice(&REFERENCE[at..at + 4 + len]);
            }
            at += 4 + len;
        }
        let got = ours();
        assert_eq!(got.len(), expected.len(), "length differs");
        if got != expected {
            let at = got.iter().zip(&expected).position(|(a, b)| a != b).unwrap();
            panic!("first difference at byte {at}: ours={:02x?} expected={:02x?}",
                &got[at.saturating_sub(4)..(at + 8).min(got.len())],
                &expected[at.saturating_sub(4)..(at + 8).min(expected.len())]);
        }
    }
}
